// 決算情報と株価情報の検索結果を統合
const items = $input.all();
const companyInfo = $('企業情報を整形').first().json;

// 決算情報
const earningsData = items[0]?.json || {};
// 株価情報
const stockData = items[1]?.json || {};

let combinedBodyText = '';

// === 決算情報 ===
combinedBodyText += '# 決算情報\n\n';
if (earningsData.answer) {
  combinedBodyText += `## AI要約\n${earningsData.answer}\n\n`;
}
if (earningsData.results && earningsData.results.length > 0) {
  combinedBodyText += '## 検索結果\n\n';
  earningsData.results.forEach((result, index) => {
    combinedBodyText += `### ${index + 1}. ${result.title || '(タイトルなし)'}\n`;
    if (result.content) {
      combinedBodyText += `${result.content}\n`;
    }
    if (result.url) {
      combinedBodyText += `出典: ${result.url}\n`;
    }
    combinedBodyText += '\n';
  });
}

// === 株価情報 ===
combinedBodyText += '\n# 株価情報\n\n';
if (stockData.answer) {
  combinedBodyText += `## AI要約\n${stockData.answer}\n\n`;
}
if (stockData.results && stockData.results.length > 0) {
  combinedBodyText += '## 検索結果\n\n';
  stockData.results.forEach((result, index) => {
    combinedBodyText += `### ${index + 1}. ${result.title || '(タイトルなし)'}\n`;
    if (result.content) {
      combinedBodyText += `${result.content}\n`;
    }
    if (result.url) {
      combinedBodyText += `出典: ${result.url}\n`;
    }
    combinedBodyText += '\n';
  });
}

// ソースURLを収集
const sources = [];
if (earningsData.results) {
  earningsData.results.forEach(r => sources.push({ title: r.title, url: r.url, type: 'earnings' }));
}
if (stockData.results) {
  stockData.results.forEach(r => sources.push({ title: r.title, url: r.url, type: 'stock' }));
}

return [{
  json: {
    combinedBodyText,
    ticker: companyInfo.ticker,
    companyName: companyInfo.companyName,
    companyNameJa: companyInfo.companyNameJa,
    earningsAnswer: earningsData.answer || '',
    stockAnswer: stockData.answer || '',
    sources: JSON.stringify(sources),
    earningsResultCount: earningsData.results ? earningsData.results.length : 0,
    stockResultCount: stockData.results ? stockData.results.length : 0
  }
}];

// 要約結果をMarkdownファイル用に整形
const summaryContent = $input.item.json.message.content;
const companyInfo = $('検索結果を結合').first().json;
const sources = JSON.parse(companyInfo.sources || '[]');
const now = new Date();
const dateStr = now.toISOString().split('T')[0];
const timestamp = now.toISOString();

// ファイル名を生成
const fileName = `${companyInfo.ticker}_analysis_${dateStr}.md`;

// ソース一覧を生成（まだ含まれていない場合）
let sourceList = '';
if (sources.length > 0 && !summaryContent.includes('## 参照ソース')) {
  sourceList = '\n\n## 参照ソース\n\n';
  sources.forEach((s, i) => {
    const typeLabel = s.type === 'earnings' ? '決算' : '株価';
    sourceList += `${i + 1}. [${s.title}](${s.url}) (${typeLabel})\n`;
  });
}

// フッターを追加
const footer = `\n\n---\n*生成日時: ${timestamp}*\n*このレポートは自動生成されました。投資判断は自己責任でお願いします。*\n`;

const finalContent = summaryContent + sourceList + footer;

return [{
  json: {
    content: finalContent,
    fileName: fileName,
    ticker: companyInfo.ticker,
    companyName: companyInfo.companyName,
    companyNameJa: companyInfo.companyNameJa,
    generatedAt: timestamp
  }
}];
